This uses sparse tables for minimum and maximum range queries. After preprocessing, a subarray query is constant time, so the remaining work is the usual two loops over all left and right boundaries.

For example, with `[1, 3, 2]`, the lookup for `[0, 2]` gives maximum `3` and minimum `1`, so that subarray contributes `2`. Equal values and negative values work the same way.

```go
func subArrayRanges(nums []int) int64 {
	n := len(nums)
	if n == 0 {
		return 0
	}

	levels := 1
	for (1 << levels) <= n {
		levels++
	}

	minTable := make([][]int, levels)
	maxTable := make([][]int, levels)
	minTable[0] = append([]int(nil), nums...)
	maxTable[0] = append([]int(nil), nums...)

	for level := 1; level < levels; level++ {
		length := n - (1 << level) + 1
		minTable[level] = make([]int, length)
		maxTable[level] = make([]int, length)
		half := 1 << (level - 1)

		for start := 0; start < length; start++ {
			minTable[level][start] = minInt(
				minTable[level-1][start],
				minTable[level-1][start+half],
			)
			maxTable[level][start] = maxInt(
				maxTable[level-1][start],
				maxTable[level-1][start+half],
			)
		}
	}

	logs := make([]int, n+1)
	for length := 2; length <= n; length++ {
		logs[length] = logs[length/2] + 1
	}

	var answer int64
	for left := 0; left < n; left++ {
		for right := left; right < n; right++ {
			length := right - left + 1
			level := logs[length]
			block := 1 << level
			minValue := minInt(minTable[level][left],
				minTable[level][right-block+1])
			maxValue := maxInt(maxTable[level][left],
				maxTable[level][right-block+1])
			answer += int64(maxValue - minValue)
		}
	}

	return answer
}

func minInt(a int, b int) int {
	if a < b {
		return a
	}
	return b
}

func maxInt(a int, b int) int {
	if a > b {
		return a
	}
	return b
}
```

Time complexity: `O(n log n + n^2)`.
Space complexity: `O(n log n)` for the two sparse tables and the log array.

I kept the direct method here. For each starting position, the subarray grows one item at a time. The current minimum and maximum are updated immediately, so there is no need to scan the same subarray again.

A one-element subarray adds zero, but it is harmless to include it. The input vector is not changed.

```cpp
class Solution {
public:
    long long subArrayRanges(vector<int> &nums) {
        long long answer = 0;
        int n = nums.size();

        for (int left = 0; left < n; ++left) {
            int currentMin = nums[left];
            int currentMax = nums[left];

            for (int right = left; right < n; ++right) {
                currentMin = min(currentMin, nums[right]);
                currentMax = max(currentMax, nums[right]);
                answer += static_cast<long long>(currentMax) - currentMin;
            }
        }

        return answer;
    }
};
```

Time complexity: `O(n^2)`.
Space complexity: `O(1)`.

The range can be split into two sums:

```text
sum of maximums - sum of minimums
```

For one element, the number of subarrays where it is the maximum is the number of choices on the left multiplied by the choices on the right. Two stacks find those limits while scanning the array. I use opposite comparisons for equal values so a subarray is not counted twice.

Dry run for `[1, 3, 2]`: the subarray ranges are `0, 0, 0, 2, 1, 2`, which gives `5`. The stack calculation produces the same total without building those subarrays.

```java
class Solution {
    public long subArrayRanges(int[] nums) {
        int n = nums.length;
        long answer = 0;
        java.util.ArrayDeque<Integer> minimumStack = new java.util.ArrayDeque<>();
        java.util.ArrayDeque<Integer> maximumStack = new java.util.ArrayDeque<>();

        for (int right = 0; right <= n; ++right) {
            while (!minimumStack.isEmpty()
                    && (right == n || nums[minimumStack.peek()] > nums[right])) {
                int middle = minimumStack.pop();
                int left = minimumStack.isEmpty() ? -1 : minimumStack.peek();
                answer -= (long) nums[middle] * (middle - left) * (right - middle);
            }

            while (!maximumStack.isEmpty()
                    && (right == n || nums[maximumStack.peek()] < nums[right])) {
                int middle = maximumStack.pop();
                int left = maximumStack.isEmpty() ? -1 : maximumStack.peek();
                answer += (long) nums[middle] * (middle - left) * (right - middle);
            }

            if (right < n) {
                minimumStack.push(right);
                maximumStack.push(right);
            }
        }

        return answer;
    }
}
```

Time complexity: `O(n)`, since every index is pushed and popped at most once in each stack.
Space complexity: `O(n)`.

I used a segment tree here as a range query exercise. Each node stores both the smallest and largest value in its interval. Then every subarray can get its range with two `O(log n)` queries.

This is not as fast as the monotonic stack method, but the query logic is fairly clear. The tree also handles negative values without any special case.

```cpp
class Solution {
    struct Node {
        int minimum;
        int maximum;
    };

    vector<Node> tree;

    void build(const vector<int>& nums, int node, int left, int right) {
        if (left == right) {
            tree[node] = {nums[left], nums[left]};
            return;
        }

        int middle = left + (right - left) / 2;
        build(nums, node * 2, left, middle);
        build(nums, node * 2 + 1, middle + 1, right);

        tree[node].minimum = min(tree[node * 2].minimum,
                                 tree[node * 2 + 1].minimum);
        tree[node].maximum = max(tree[node * 2].maximum,
                                 tree[node * 2 + 1].maximum);
    }

    Node query(int node, int left, int right, int queryLeft, int queryRight) {
        if (queryLeft <= left && right <= queryRight) {
            return tree[node];
        }

        int middle = left + (right - left) / 2;

        if (queryRight <= middle) {
            return query(node * 2, left, middle, queryLeft, queryRight);
        }
        if (queryLeft > middle) {
            return query(node * 2 + 1, middle + 1, right,
                         queryLeft, queryRight);
        }

        Node first = query(node * 2, left, middle, queryLeft, queryRight);
        Node second = query(node * 2 + 1, middle + 1, right,
                           queryLeft, queryRight);

        return {min(first.minimum, second.minimum),
                max(first.maximum, second.maximum)};
    }

public:
    long long subArrayRanges(vector<int> &nums) {
        int n = nums.size();
        if (n == 0) {
            return 0;
        }

        tree.assign(4 * n, {0, 0});
        build(nums, 1, 0, n - 1);

        long long answer = 0;
        for (int left = 0; left < n; ++left) {
            for (int right = left; right < n; ++right) {
                Node current = query(1, 0, n - 1, left, right);
                answer += static_cast<long long>(current.maximum)
                        - current.minimum;
            }
        }

        return answer;
    }
};
```

Time complexity: `O(n^2 log n)` after `O(n)` tree construction.
Space complexity: `O(n)` for the segment tree.

## Intuition

For every subarray, we need:

```text
maximum - minimum
```

Instead of generating every subarray, calculate these two values separately:

```text
sum of all subarray maximums
-
sum of all subarray minimums
```

For each element `nums[i]`, determine how many subarrays use it as:

- the minimum
- the maximum

If an element is the minimum in `left × right` subarrays, its total contribution is:

```text
nums[i] × left × right
```

Monotonic stacks efficiently find the boundaries where an element stops being the minimum or maximum.

---

## Approach

### 1. Find the contribution as a minimum

For every index `i`, find:

- `PSEE`: Previous Smaller Element or Equal
- `NSE`: Next Smaller Element

```cpp
left = i - psee[i]
right = nse[i] - i
```

The number of subarrays where `nums[i]` is the minimum is:

```cpp
left × right
```

Therefore, its contribution is:

```cpp
nums[i] × left × right
```

For duplicate values, the comparisons are intentionally asymmetric:

```cpp
PSEE: while (nums[st.top()] > nums[i])
NSE : while (nums[st.top()] >= nums[i])
```

This prevents duplicate elements from being counted more than once.

---

### 2. Find the contribution as a maximum

Similarly, for every index `i`, find:

- `PGEE`: Previous Greater Element or Equal
- `NGE`: Next Greater Element

Then:

```cpp
left = i - pgee[i]
right = nge[i] - i
```

The number of subarrays where `nums[i]` is the maximum is:

```cpp
left × right
```

Its contribution is:

```cpp
nums[i] × left × right
```

For maximums, the duplicate-handling comparisons are:

```cpp
PGEE: while (nums[st.top()] < nums[i])
NGE : while (nums[st.top()] <= nums[i])
```

---

### 3. Calculate the final answer

Finally:

```cpp
sum of subarray maximums - sum of subarray minimums
```

This works because:

```text
Σ(max(subarray) - min(subarray))
=
Σ(max(subarray)) - Σ(min(subarray))
```

The boundary values `-1` and `nums.size()` represent cases where no smaller or greater element exists on that side.

---

## Solution

```cpp
class Solution {
private:
    vector<int> findPSEE(vector<int> &nums){
        stack<int> st;
        vector<int> res(nums.size());
        for(int i = 0; i < nums.size(); i++){
            while(!st.empty() && nums[st.top()] > nums[i]){
                st.pop();
            }
            res[i] = !st.empty()?st.top(): -1;

            st.push(i);
        }
        return res;
    }
    vector<int> findNSE(vector<int> &nums){
        stack<int> st;
        vector<int> res(nums.size());
        for(int i = nums.size()-1; i >= 0; i--){
            while(!st.empty() && nums[st.top()] >= nums[i]){
                st.pop();
            }
            res[i] = !st.empty()?st.top(): nums.size();
            st.push(i);
        }
        return res;
    }
    vector<int> findPGEE(vector<int> &nums){
        stack<int> st;
        vector<int> res(nums.size());
        for(int i = 0; i < nums.size(); i++){
            while(!st.empty() && nums[st.top()] < nums[i]){
                st.pop();
            }
            res[i] = !st.empty()?st.top(): -1;
            st.push(i);
        }
        return res;
    }
    vector<int> findNGE(vector<int> &nums){
        stack<int> st;
        vector<int> res(nums.size());
        for(int i = nums.size()-1; i >= 0; i--){
            while(!st.empty() && nums[st.top()] <= nums[i]){
                st.pop();
            }
            res[i] = !st.empty()?st.top(): nums.size();
            st.push(i);
        }
        return res;
    }
    long long sumSubArrMins(vector<int> &nums){
        vector<int> psee = findPSEE(nums);
        vector<int> nse = findNSE(nums);

        long long val = 0;
        for(int i = 0; i < nums.size(); i++){
            long long l = i - psee[i];
            long long r = nse[i] - i;
            long long freq = l*r;
            val = (val + freq*nums[i]);
        }
        return val;
    }
    long long sumSubArrMaxs(vector<int> &nums){
        vector<int> pgee = findPGEE(nums);
        vector<int> nge = findNGE(nums);
        long long val = 0;
        for(int i = 0; i < nums.size(); i++){
            long long l = i - pgee[i];
            long long r = nge[i] - i;
            long long freq = l*r;
            val = (val + freq*nums[i]);
        }
        return val;
    }

public:
    long long subArrayRanges(vector<int> &nums) {
        // long long ans = 0;
