class Solution {
  subArrayRanges(nums) {
    return this.findMaxSubArrSum(nums) - this.findMinSubArrSum(nums);
  }
  findMaxSubArrSum(arr) {
    let total = 0;
    const NGE = this.findNextGreaterElements(arr);
    const PGEE = this.findPrevGreaterElements(arr);
    for (let i = 0; i < arr.length; i++) {
      const right = NGE[i] - i;
      const left = i - PGEE[i];
      total += left * right * arr[i];
    }
    return total;
  }
  findMinSubArrSum(arr) {
    let total = 0;
    const NSE = this.findNextSmallElements(arr);
    const PSEE = this.findPrevSmallElements(arr);
    for (let i = 0; i < arr.length; i++) {
      const right = NSE[i] - i;
      const left = i - PSEE[i];
      total += left * right * arr[i];
    }
    return total;
  }

  findNextSmallElements(arr) {
    const n = arr.length;
    const ans = new Array(n);
    const stack = [];
    for (let i = n - 1; i >= 0; i--) {
      while (stack.length && stack[stack.length - 1][0] > arr[i]) {
        stack.pop();
      }
      if (stack.length === 0) {
        ans[i] = n;
      } else {
        ans[i] = stack[stack.length - 1][1];
      }
      stack.push([arr[i], i]);
    }
    return ans;
  }
  findPrevSmallElements(arr) {
    const n = arr.length;
    const ans = new Array(n);
    const stack = [];
    for (let i = 0; i < n; i++) {
      while (stack.length && stack[stack.length - 1][0] >= arr[i]) {
        stack.pop();
      }
      if (stack.length === 0) {
        ans[i] = -1;
      } else {
        ans[i] = stack[stack.length - 1][1];
      }
      stack.push([arr[i], i]);
    }
    return ans;
  }
  findNextGreaterElements(arr) {
    const n = arr.length;
    const ans = new Array(n);
    const stack = [];
    for (let i = n - 1; i >= 0; i--) {
      while (stack.length && stack[stack.length - 1][0] < arr[i]) {
        stack.pop();
      }
      if (stack.length === 0) {
        ans[i] = n;
      } else {
        ans[i] = stack[stack.length - 1][1];
      }
      stack.push([arr[i], i]);
    }
    return ans;
  }
  findPrevGreaterElements(arr) {
    const n = arr.length;
    const ans = new Array(n);
    const stack = [];
    for (let i = 0; i < n; i++) {
      while (stack.length && stack[stack.length - 1][0] <= arr[i]) {
        stack.pop();
